// @ts-check
/**
 * Documentation search dialog (PRD §7, spec S5). Imported by the inline loader (bootstrap.ts) the
 * first time a [data-search-open] trigger is clicked, never before. It loads Pagefind's static index
 * from /pagefind/ (generated by `pnpm build`, same origin, no third parties) and renders results
 * into the dialog of DocsSearch.astro. Plain JavaScript: Vite emits it unchanged through `?url`.
 *
 * Results only use classes and the `hidden` attribute (no inline styles: CSP). Pagefind's excerpt is
 * HTML-escaped text with <mark> around matches, so it is the only markup inserted as HTML.
 */

/** Results shown per query. */
export const MAX_RESULTS = 8;

/**
 * Site URL of a Pagefind result. Pages are built as files (build.format "file"), so Pagefind
 * reports "/docs/a/b.html"; the site links "/docs/a/b" (trailingSlash "never").
 * @param {string} url
 */
export function pageUrl(url) {
  const cut = url.search(/[?#]/);
  const path = cut < 0 ? url : url.slice(0, cut);
  const rest = cut < 0 ? "" : url.slice(cut);
  const clean = path.replace(/\.html$/, "").replace(/\/index$/, "") || "/";
  return clean + rest;
}

/**
 * The items to render from Pagefind result data.
 * @param {{ url: string; excerpt: string; meta?: { title?: string } }[]} data
 */
export function resultItems(data) {
  return data.map((d) => ({ href: pageUrl(d.url), title: d.meta?.title ?? pageUrl(d.url), excerpt: d.excerpt }));
}

/**
 * Status line for a finished query.
 * @param {number} count
 * @param {string} query
 * @param {{ one: string; many: string; none: string }} labels "{n}" and "{q}" are replaced.
 */
export function statusText(count, query, labels) {
  const template = count === 0 ? labels.none : count === 1 ? labels.one : labels.many;
  return template.replace("{n}", String(count)).replace("{q}", query);
}

/** Pagefind's runtime, written to dist/pagefind by `pagefind --site dist`; a variable, so neither
 * Vite nor TypeScript try to resolve it at build time. */
const PAGEFIND = "/pagefind/pagefind.js";

/** @type {Promise<any> | null} */
let engine = null;

/** Pagefind, loaded once per page on first use. */
function loadEngine() {
  engine ??= import(/* @vite-ignore */ PAGEFIND).then(async (pf) => {
    await pf.options({ baseUrl: "/" });
    pf.init();
    return pf;
  });
  return engine;
}

/** @param {HTMLDialogElement} dialog */
function wire(dialog) {
  const input = /** @type {HTMLInputElement} */ (dialog.querySelector("input[type=search]"));
  const list = /** @type {HTMLOListElement} */ (dialog.querySelector("[data-results]"));
  const status = /** @type {HTMLElement} */ (dialog.querySelector("[data-status]"));
  const d = dialog.dataset;
  const labels = { one: d.one ?? "", many: d.many ?? "", none: d.none ?? "" };
  let run = 0;

  const render = (/** @type {ReturnType<typeof resultItems>} */ items) => {
    list.replaceChildren(
      ...items.map((item) => {
        const li = document.createElement("li");
        const a = document.createElement("a");
        a.href = item.href;
        const title = document.createElement("span");
        title.className = "result-title";
        title.textContent = item.title;
        const excerpt = document.createElement("span");
        excerpt.className = "result-excerpt";
        excerpt.innerHTML = item.excerpt;
        a.append(title, excerpt);
        li.append(a);
        return li;
      }),
    );
  };

  const search = async () => {
    const query = input.value.trim();
    const mine = ++run;
    if (!query) {
      render([]);
      status.textContent = d.idle ?? "";
      return;
    }
    try {
      const pf = await loadEngine();
      const found = await pf.debouncedSearch(query, {}, 150);
      if (found === null || mine !== run) return;
      const data = await Promise.all(found.results.slice(0, MAX_RESULTS).map((/** @type {any} */ r) => r.data()));
      if (mine !== run) return;
      render(resultItems(data));
      status.textContent = statusText(found.results.length, query, labels);
    } catch {
      if (mine !== run) return;
      render([]);
      status.textContent = d.unavailable ?? "";
    }
  };

  input.addEventListener("input", () => void search());
  dialog.querySelector("[data-search-close]")?.addEventListener("click", () => dialog.close());
  // A click on the backdrop (the dialog element itself, outside its panel) closes it.
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });
  status.textContent = d.idle ?? "";
  dialog.dataset.wired = "";
}

/**
 * Opens the search dialog the trigger controls (aria-controls) and starts loading the index.
 * @param {HTMLElement} trigger
 */
export function open(trigger) {
  const dialog = /** @type {HTMLDialogElement | null} */ (document.getElementById(trigger.getAttribute("aria-controls") ?? ""));
  if (!dialog) return;
  if (!("wired" in dialog.dataset)) wire(dialog);
  dialog.showModal();
  dialog.querySelector("input")?.focus();
  void loadEngine().catch(() => {});
}
